const ymd=d=>d.getUTCFullYear()+'.'+String(d.getUTCMonth()+1).padStart(2,'0')+'.'+String(d.getUTCDate()).padStart(2,'0');
const md=d=>d.slice(5),DOW=['일','월','화','수','목','금','토'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DKO={easy:'이지',normal:'노멀',hard:'하드',chaos:'카오스',extreme:'익스트림'};
function meso(v){if(v==null)return null;v=Math.round(v);const e=Math.floor(v/1e8),m=Math.floor(v%1e8/1e4),r=v%1e4;const out=[];if(e)out.push(e+'억');if(m)out.push(m+'만');if(r&&!e)out.push(String(r));return out.join(' ')||'0'}
function sil(size){return `<svg width="${size*.64}" height="${size*.78}" viewBox="0 0 70 100" aria-hidden="true"><circle cx="35" cy="30" r="20" fill="var(--faint)"/><path d="M12 100c0-24 8-44 23-44s23 20 23 44z" fill="var(--faint)"/></svg>`}
