const sxD=s=>{const[y,m,d]=s.split('.').map(Number);return new Date(Date.UTC(y,m-1,d))};
const sxAdd=(s,n)=>ymd(new Date(sxD(s).getTime()+n*864e5));
const sxWeek=s=>{const d=sxD(s),back=(d.getUTCDay()-4+7)%7;return ymd(new Date(d.getTime()-back*864e5))}; // 목요일 시작
